// Remove Markdown code block and parse JSON
let raw = $json.output || "";
raw = raw.replace(/```json|```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { error: "Failed to parse AI output", raw_output: raw };
}

return parsed;

